import sys,json,html,math
from pathlib import Path
ROOT=Path(__file__).parent
sys.path.insert(0,str(ROOT/'.libs'))
from shapely.geometry import shape,Polygon,box,mapping
from shapely.ops import unary_union,transform
from shapely import make_valid
from pyproj import Transformer
D={y:json.loads((ROOT/f'datos/world_{y}.geojson').read_text(encoding='utf-8')) for y in [1914,1920]}
def get(y,name):
 return unary_union([make_valid(shape(f['geometry'])) for f in D[y]['features'] if f['properties']['NAME']==name])
clip=box(-15,29,49,70)
proj=Transformer.from_crs('EPSG:4326','+proj=lcc +lat_1=35 +lat_2=65 +lat_0=50 +lon_0=15 +datum=WGS84',always_xy=True).transform
regions=[]
def add(name,g,color,kind,note):
 g=make_valid(g).intersection(clip)
 if not g.is_empty:regions.append(dict(name=name,g=g,color=color,kind=kind,note=note))
colors={'German Empire':'#6b7880','Austro-Hungarian Empire':'#c7aa50','Ottoman Empire':'#b97a68','Bulgaria':'#7c986d','France':'#9fb9cf','United Kingdom of Great Britain and Ireland':'#c39396','Kingdom of Italy':'#a9c1a0','Russian Empire':'#cabba3'}
es={'German Empire':'Imperio alemán','Austro-Hungarian Empire':'Austria-Hungría','Ottoman Empire':'Imperio otomano','Bulgaria':'Bulgaria','France':'Francia','United Kingdom of Great Britain and Ireland':'Reino Unido e Irlanda','Kingdom of Italy':'Italia','Russian Empire':'Rusia','Belgium':'Bélgica','Romania':'Rumanía','Serbia':'Serbia','Montenegro':'Montenegro','Albania':'Albania','Spain':'España','Portugal':'Portugal','Switzerland':'Suiza','Netherlands':'Países Bajos','Denmark':'Dinamarca','Sweden':'Suecia','Norway':'Noruega','Greece':'Grecia'}
for f in D[1914]['features']:
 n=f['properties']['NAME'] or 'Territorio sin identificar';g=make_valid(shape(f['geometry']))
 if not g.intersects(clip):continue
 col=colors.get(n,'#d8d2bf');kind='Estado de referencia';note='Base territorial de 1914; soberanía y fronteras posteriores dependen de la paz hipotética.'
 if n in ['German Empire','Austro-Hungarian Empire','Ottoman Empire','Bulgaria']:kind='Potencia central';note='Supervivencia del Estado tras la victoria; fronteras de base de 1914.'
 if n in ['Belgium','Romania','Serbia','Montenegro']:col='#d6b48b';kind='Soberanía restringida — hipótesis';note='Se supone un Estado superviviente sometido a condiciones militares y económicas; no una anexión íntegra.'
 if n=='Luxembourg':col='#6b7880';kind='Anexión propuesta';note='Incorporación a Alemania prevista en el Septemberprogramm; realizada solo en este escenario.'
 add(es.get(n,n),g,col,kind,note)
russia=get(1914,'Russian Empire')
for n,label,lon,lat in [('Finland','Finlandia',25,64),('Estonia','Ducado Báltico',26,58),('Latvia','Ducado Báltico',25,57),('Lithuania','Lituania',24,55),('Poland','Polonia',21,52),('Ukraine','Ucrania',32,49)]:
 g=get(1920,n) if n=='Finland' else get(1920,n).intersection(russia)
 add(label,g,'#b8c2c3','Estado vinculado a Alemania — hipótesis','Proyecto político inspirado en 1918. Contorno orientativo derivado de la base de 1920 y recortado al Imperio ruso de 1914; no es una frontera pactada en Brest-Litovsk. Finlandia se interpreta como aliada, no como territorio anexionado.')
serb=get(1914,'Serbia');rom=get(1914,'Romania')
mac=Polygon([(20.45,40.7),(23,40.7),(23,42.35),(21.5,42.35),(20.45,41.6)])
dob=Polygon([(27.1,43.7),(28.7,43.7),(29.7,45.45),(28.7,45.45),(28.1,44.5)])
add('Macedonia del Vardar',serb.intersection(mac),'#7c986d','Ampliación búlgara — hipótesis','Transferencia hipotética basada en objetivos búlgaros y ocupación de guerra; delimitación aproximada.')
add('Dobruja: reparto pendiente',rom.intersection(dob),'#7c986d','Reparto de 1918 simplificado','Se representa la expansión búlgara y el área de reparto. El norte de Dobruja no fue íntegramente adjudicado a Bulgaria en el tratado de mayo de 1918.')
uncertain=[('Reclamaciones en Bélgica y Briey',Polygon([(4.8,49),(6.3,49),(6.3,50.1),(5.4,50.2)]).intersection(unary_union([get(1914,'France'),get(1914,'Belgium')]))),('Frontera polaco-rusa no resuelta',get(1920,'White Russia').intersection(russia)),('Rectificaciones carpáticas',rom.intersection(Polygon([(22.4,44.6),(25.5,45.6),(26.7,47.5),(25.8,48),(24.5,46.5)])))]
for n,g in uncertain:add(n,g,'url(#hatch)','Zona de negociación','Trama indicativa de reclamación o delimitación incierta; no expresa una cesión territorial exacta.')
W,H=1600,1280
def xy(lon,lat):
 x,y=proj(lon,lat);return (800+x/4300,590-y/4300)
def path(g):
 out=[]
 if g.geom_type=='Polygon':
  for ring in [g.exterior,*g.interiors]:
   pts=[xy(*p[:2]) for p in ring.coords];out.append('M'+' L'.join(f'{x:.1f},{y:.1f}' for x,y in pts)+' Z')
 elif hasattr(g,'geoms'):
  for q in g.geoms:out.append(path(q))
 return ' '.join(out)
svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="1280" viewBox="0 0 1600 1280"><defs><pattern id="hatch" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><rect width="3" height="8" fill="#74533c" opacity=".65"/></pattern><clipPath id="mapclip"><rect x="24" y="126" width="1552" height="920" rx="8"/></clipPath></defs><style>text{font-family:Segoe UI,Arial,sans-serif}.label{font-size:19px;font-weight:650;fill:#263336;paint-order:stroke;stroke:#f7f3e7;stroke-width:3px;stroke-linejoin:round}.small{font-size:14px;fill:#53666a}.country{cursor:pointer;transition:filter .15s}.country:hover{filter:brightness(1.12);stroke:#182c33;stroke-width:2}</style><rect width="1600" height="1280" fill="#f5f0e5"/><text x="48" y="43" font-size="13" letter-spacing="4" fill="#8a5147">ATLAS DE HISTORIAS POSIBLES · 01</text><text x="48" y="85" font-family="Georgia" font-size="37" fill="#24383e">Europa tras una victoria de las Potencias Centrales</text><text x="48" y="112" class="small">1920 alternativo · Paz negociada tras una victoria en 1918 · Escenario interpretativo, no reparto histórico aprobado</text><g clip-path="url(#mapclip)"><rect x="24" y="126" width="1552" height="920" fill="#dce8e8"/>']
for lon in range(-10,51,10):
 pts=[xy(lon,lat) for lat in range(28,73)];svg.append('<path d="M'+' L'.join(f'{x:.1f},{y:.1f}' for x,y in pts)+'" fill="none" stroke="#c7d8d8" stroke-width="1"/>')
for lat in range(30,71,10):
 pts=[xy(lon,lat) for lon in range(-20,61)];svg.append('<path d="M'+' L'.join(f'{x:.1f},{y:.1f}' for x,y in pts)+'" fill="none" stroke="#c7d8d8" stroke-width="1"/>')
for i,r in enumerate(regions):
 title=html.escape(r['name']+' — '+r['kind']+'\n'+r['note']);svg.append(f'<path class="country" data-i="{i}" d="{path(r["g"])}" fill="{r["color"]}" stroke="#f4f0e7" stroke-width="1.1" fill-rule="evenodd"><title>{title}</title></path>')
labels=[('IMPERIO ALEMÁN',10.5,51.2),('AUSTRIA-HUNGRÍA',17.1,47.5),('IMPERIO OTOMANO',33,38.5),('BULGARIA',25,42.7),('FRANCIA',2,46.5),('ITALIA',12.5,42),('RUSIA',41,57),('Finlandia',26,64),('Ducado Báltico*',26,58),('Lituania*',24,55),('Polonia*',22,52),('Ucrania*',33,49),('ESPAÑA',-1,40),('PORTUGAL',-10,39),('SUECIA',16,63),('NORUEGA',7,63),('REINO UNIDO',-3,55),('e Irlanda',-3,53.8),('Rumanía',25,45.6),('Serbia',20.4,44),('Grecia',23,38),('Albania',18.4,40),('Suiza',7.5,46.8),('Bélgica',2.4,50.7),('Países Bajos',3.5,53),('Dinamarca',9,56.8)]
for name,lon,lat in labels:
 x,y=xy(lon,lat);svg.append(f'<text x="{x:.1f}" y="{y:.1f}" text-anchor="middle" class="label" style="font-size:{15 if name in ["Bélgica","Países Bajos","Suiza","Albania","Serbia","Rumanía"] else 19}px">{name}</text>')
svg+=['<rect x="47" y="815" width="470" height="206" rx="8" fill="#fbf8ef" opacity=".96"/><text x="66" y="844" font-size="18" font-weight="700" fill="#24383e">CÓMO LEER EL MAPA</text>']
for j,(col,txt) in enumerate([('#6b7880','Alemania · gris; socios centrales · colores propios'),('#b8c2c3','Estados del este vinculados a Alemania*'),('#d6b48b','Estados vencidos con soberanía restringida'),('url(#hatch)','Reclamaciones o fronteras inciertas'),('#d8d2bf','Otros Estados · colores de referencia')]):
 y=860+j*28;svg.append(f'<rect x="67" y="{y}" width="22" height="16" fill="{col}" stroke="#8a918a"/><text x="101" y="{y+13}" font-size="14" fill="#35494b">{txt}</text>')
svg+=['</g><text x="48" y="1083" font-size="18" font-weight="650" fill="#24383e">Una hegemonía alemana, con varios grados de dependencia</text><text x="48" y="1111" class="small">* Contornos orientativos: base de 1920 recortada a Rusia de 1914. No equivalen a las fronteras exactas de los proyectos de 1918.</text><text x="48" y="1135" class="small">Austria-Hungría conserva su estructura territorial. El mapa no presupone su federalización ni la anexión completa de Serbia.</text><text x="48" y="1159" class="small">Los otomanos conservan aquí su espacio de 1914: exige una paz favorable y recuperar zonas ocupadas. El Cáucaso queda sin resolver.</text><text x="48" y="1183" class="small">No se representan colonias ni un reparto mundial. Francia y Reino Unido sobreviven como potencias independientes.</text><text x="48" y="1220" font-size="12" fill="#6b7775">Base geográfica: Historical Basemaps, André Ourednik y colaboradores · 1914 / 1920 · Proyección cónica conforme de Lambert</text><text x="48" y="1243" font-size="12" fill="#6b7775">Fundamento: Septemberprogramm (1914), Brest-Litovsk y proyectos orientales (1918), objetivos búlgaros y paz de Bucarest (1918).</text></svg>']
SVG=''.join(svg);(ROOT/'europa_victoria_centrales.svg').write_text(SVG,encoding='utf-8')
data=[{k:v for k,v in r.items() if k!='g'} for r in regions]
sources=[('Septemberprogramm · Deutsches Historisches Museum','https://www.dhm.de/lemo/kapitel/erster-weltkrieg/innenpolitik/septemberprogramm'),('Brest-Litovsk · documento diplomático de 1918','https://avalon.law.yale.edu/20th_century/bl34.asp'),('Objetivos búlgaros · declaración de 1917','https://history.state.gov/historicaldocuments/frus1917Supp02v01/d404'),('Báltico y Finlandia · documentación diplomática','https://history.state.gov/historicaldocuments/frus1919Parisv12/d66'),('Dobruja · estudio oficial de fronteras','https://library.law.fsu.edu/Digital-Collections/LimitsinSeas/pdf/ibs053.pdf'),('Cartografía y licencia · Historical Basemaps','https://github.com/aourednik/historical-basemaps')]
page='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Victoria de las Potencias Centrales · 1920 alternativo</title><style>body{margin:0;background:#f5f0e5;color:#263b40;font:16px/1.55 system-ui}nav{padding:14px 24px;background:#24383e;color:white;display:flex;gap:18px;align-items:center;flex-wrap:wrap}button,a{color:inherit}button{background:#f5f0e5;color:#24383e;border:0;border-radius:5px;padding:8px 14px;cursor:pointer}#map{overflow:auto}svg{display:block;width:100%;height:auto;min-width:900px}#detail{padding:20px 28px;border-block:1px solid #c5c9bd;background:#fffbf2;min-height:80px}article{max-width:1000px;padding:30px;margin:auto}h1{font:32px Georgia}li{margin:10px 0}a{color:#835247}nav a{color:white}</style><nav><b>Atlas · Europa alternativa</b><button id="save">Descargar SVG</button><button id="zoom">Ampliar / ajustar</button><a href="europa_victoria_centrales.png">Abrir PNG</a><a href="#contexto">Supuestos y fuentes</a></nav><div id="map">'''+SVG+'''</div><section id="detail" aria-live="polite">Selecciona un territorio para ver su papel en el escenario. La leyenda está dentro del mapa.</section><article id="contexto"><h1>Qué tuvo que cambiar</h1><p>Se supone que una crisis militar aliada en 1918 conduce a una paz favorable a las Potencias Centrales antes del colapso de sus imperios. El mapa ilustra un orden posible hacia 1920, condicionado a que Alemania sostenga sus acuerdos orientales y a que Austria-Hungría y el Imperio otomano superen sus crisis internas. No representa un desenlace inevitable ni un único plan acordado por los cuatro aliados.</p><p><b>Occidente:</b> Francia conserva su Estado y Alsacia-Lorena permanece en Alemania, como en 1914. Luxemburgo se incorpora hipotéticamente al Reich; Bélgica queda subordinada, sin asumir su anexión completa. El tramado del oeste indica reclamaciones, no una frontera aprobada.</p><p><b>Oriente:</b> se prolonga la influencia alemana sobre Polonia, Lituania, el proyecto de Ducado Báltico y Ucrania. Finlandia figura como aliada vinculada a Alemania, sin equiparar su posición a la de un Estado ocupado. Las fronteras de 1920 sirven solo de aproximación visual: no reproducen los límites exactos del Congreso de Polonia ni de cada proyecto monárquico de 1918. Rusia conserva un espacio político cuyo régimen y guerra civil no se resuelven aquí.</p><p><b>Balcanes:</b> Bulgaria obtiene una expansión aproximada en Macedonia del Vardar. Dobruja se presenta como área de reparto: el tratado de mayo de 1918 distinguía cesiones búlgaras y administración común en el norte. Serbia, Montenegro y Rumanía sobreviven bajo restricciones hipotéticas. Las rectificaciones carpáticas se señalan como inciertas.</p><p><b>Otomanos:</b> conservar los territorios de 1914 es una hipótesis favorable, no la situación militar real de 1918. Arabia, Mesopotamia, Palestina y el Cáucaso requerirían acuerdos específicos que esta vista europea no delimita.</p><h2>Fuentes</h2><ul>'''+''.join(f'<li><a href="{u}">{html.escape(t)}</a></li>' for t,u in sources)+'''</ul><p>Las geometrías originales de 1914 y 1920 se guardan en <code>datos/</code>. La generalización cartográfica permite una lectura continental; no una delimitación local. Consulta el repositorio de origen para su licencia y atribuciones.</p></article><script>const data='''+json.dumps(data,ensure_ascii=False)+''';document.querySelectorAll('.country').forEach(p=>p.addEventListener('click',()=>{const r=data[p.dataset.i];const e=document.getElementById('detail');e.replaceChildren();const b=document.createElement('b');b.textContent=r.name+' · '+r.kind;e.append(b,document.createElement('br'),document.createTextNode(r.note))}));document.getElementById('zoom').onclick=()=>{const s=document.querySelector('svg');s.style.width=s.style.width==='180%'?'100%':'180%'};document.getElementById('save').onclick=()=>{const s=document.querySelector('svg').cloneNode(true);s.style.width='';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(s)],{type:'image/svg+xml'}));a.download='europa_victoria_centrales.svg';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};</script></html>'''
(ROOT/'europa_victoria_centrales.html').write_text(page,encoding='utf-8')
(ROOT/'datos/escenario.geojson').write_text(json.dumps({'type':'FeatureCollection','features':[{'type':'Feature','properties':{k:v for k,v in r.items() if k!='g'},'geometry':mapping(r['g'])} for r in regions]},ensure_ascii=False),encoding='utf-8')
print('Generados HTML, SVG y GeoJSON;',len(regions),'regiones')

